import{_ as a,C as i,o as s,c as o,E as r,a2 as n}from"./chunks/framework.BEADHO7-.js";const k=JSON.parse('{"title":"Luaスクリプトで動かす（Scripting）","description":"Lua 5.4スクリプトで毎フレームの文字・パーツをプロシージャルに制御するスクリプティング機能の使い方","frontmatter":{"title":"Luaスクリプトで動かす（Scripting）","description":"Lua 5.4スクリプトで毎フレームの文字・パーツをプロシージャルに制御するスクリプティング機能の使い方","pageClass":"feature-guide","aside":false,"head":[["link",{"rel":"canonical","href":"https://mug-lab-3.github.io/mug-typography-docs/features/feature-scripting.html"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mug Typography Manual"}],["meta",{"property":"og:locale","content":"ja_JP"}],["meta",{"property":"og:title","content":"Luaスクリプトで動かす（Scripting） | Mug Typography Manual"}],["meta",{"property":"og:description","content":"Lua 5.4スクリプトで毎フレームの文字・パーツをプロシージャルに制御するスクリプティング機能の使い方"}],["meta",{"property":"og:url","content":"https://mug-lab-3.github.io/mug-typography-docs/features/feature-scripting.html"}],["meta",{"property":"og:image","content":"https://mug-lab-3.github.io/mug-typography-docs/image/social-card.png"}],["meta",{"property":"og:image:type","content":"image/png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:image:alt","content":"Mug Typography Online Manual"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:site","content":"@MugLab3"}],["meta",{"name":"twitter:title","content":"Luaスクリプトで動かす（Scripting） | Mug Typography Manual"}],["meta",{"name":"twitter:description","content":"Lua 5.4スクリプトで毎フレームの文字・パーツをプロシージャルに制御するスクリプティング機能の使い方"}],["meta",{"name":"twitter:image","content":"https://mug-lab-3.github.io/mug-typography-docs/image/social-card.png"}],["meta",{"name":"twitter:image:alt","content":"Mug Typography Online Manual"}]]},"headers":[],"relativePath":"features/feature-scripting.md","filePath":"features/feature-scripting.md"}'),p={name:"features/feature-scripting.md"};function c(l,t,d,g,h,u){const e=i("FeatureHero");return s(),o("div",null,[r(e,{"is-new":"",eyebrow:"LUA SCRIPTING",title:"スクリプトで文字を動かす",description:"波打ち、ランダム散らし、物理風の動きなど、キーフレームでは作りにくいアニメーションを短いスクリプトで実現。付属のVSCode用シミュレーターを使えば、DaVinci Resolveを起動せずに開発・プレビューできます。",image:"/image/scripting-hero.webp","image-alt":"Luaスクリプトで制御された文字アニメーション","detail-link":"/reference/reference-scripting-settings","point-one":"毎フレームをコードで制御","point-two":"VSCodeシミュレーター付属","point-three":"豊富なサンプルスクリプト"}),t[0]||(t[0]=n(`<h2 id="使い方" tabindex="-1">使い方 <a class="header-anchor" href="#使い方" aria-label="Permalink to &quot;使い方&quot;">​</a></h2><p>通常の2D / 3D / Liteプリセットでは、次の手順で有効にします。</p><ol><li><strong>Page</strong> を <code>Scripting</code> にします。</li><li><strong>Script Enabled</strong> をONにします。</li><li><strong>Script Text</strong> にLuaスクリプトを入力するか、<strong>Paste Script</strong> でクリップボードから貼り付けます。</li></ol><p><code>Mug Typography Scripting</code>プリセットでは、Scriptingグループが<strong>Globalページ内</strong>に表示されるため、Pageの切り替えは不要です。このプリセットはCharacter SettingsとPart Settingsを省略して最大512文字・1024パーツを扱え、個々の文字・パーツはLuaから制御します。インスペクタでの個別編集とLuaを併用したい場合は、通常のプリセットを使用してください。</p><p>たとえば次のスクリプトだけで、全文字がそれぞれ位相をずらしながら揺れ続けます。</p><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> OnLayout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ctx)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> index, character </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> mt.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">each_char</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ctx) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">do</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        character.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rotation</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> math.sin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ctx.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">time</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2.0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> index </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 15.0</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        character.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">offset_y</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> math.sin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ctx.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">time</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3.0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> index </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.7</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.02</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    end</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">end</span></span></code></pre></div><p>スクリプトはインスペクタの値を毎フレーム上書きする形で動作します。キーフレームや他の機能（デフォーム、Write On、3Dなど）とそのまま併用できます。</p><p>時間に依存しない静的な配置や装飾では、<code>-- @time_independent</code> を宣言すると、値が変わらないフレームでLuaの実行と文字の再描画を省略できます。上の例は <code>ctx.time</code> で動くため、宣言を追加しないでください。条件と静的な使用例は「<a href="/mug-typography-docs/reference/reference-scripting-settings.html#time-independent">時間非依存の宣言と描画結果の再利用</a>」を参照してください。</p><h2 id="_3つのコールバック" tabindex="-1">3つのコールバック <a class="header-anchor" href="#_3つのコールバック" aria-label="Permalink to &quot;3つのコールバック&quot;">​</a></h2><p>スクリプトには最大3つの関数を定義できます。必要な関数だけを書けば動作します。</p><table tabindex="0"><thead><tr><th>コールバック</th><th>実行タイミング</th><th>主な用途</th></tr></thead><tbody><tr><td><code>OnPreLayout(ctx)</code></td><td>文字を並べる<strong>前</strong>（毎フレーム）</td><td>テキスト内容・字送り・整列・全体色・カメラの変更、図形やカスタムグリフの宣言</td></tr><tr><td><code>OnLayout(ctx)</code></td><td>文字を並べた<strong>後</strong>（毎フレーム）</td><td>1文字ごと・パーツごと・図形ごとの位置、回転、スケール、色などの変更</td></tr><tr><td><code>OnPath(ctx)</code></td><td><code>OnLayout</code> の後（毎フレーム）</td><td><code>ctx.paths</code> で選んだパーツや図形の輪郭をカスタムパスに差し替え</td></tr></tbody></table><p>まず <code>OnPreLayout</code> でテキスト全体の条件を決め、その条件で並んだ文字やパーツを <code>OnLayout</code> で個別に動かす、という2段階の流れになっています。そのため、文字数や改行が変わる処理（タイプライター演出など）は <code>OnPreLayout</code> に書き、各文字やパーツを動かす処理は <code>OnLayout</code> に書きます。</p><p><code>mt.*</code> には、文字・パーツを順番に処理する <code>mt.each_char</code> / <code>mt.each_part</code>、数値計算（<code>mt.clamp</code> / <code>mt.lerp</code> / <code>mt.remap</code>）、イージング（<code>mt.ease.*</code>）、色変換（<code>mt.color.*</code>）、タイムライン制御（<code>mt.timeline.*</code>）、SVGパス構築（<code>mt.svg_path</code>）などの補助関数が揃っています。</p><h2 id="図形-シェイプ-とカスタムグリフを描く" tabindex="-1">図形（シェイプ）とカスタムグリフを描く <a class="header-anchor" href="#図形-シェイプ-とカスタムグリフを描く" aria-label="Permalink to &quot;図形（シェイプ）とカスタムグリフを描く&quot;">​</a></h2><p>スクリプトからは、文字を動かすだけでなく、任意のベクター図形やSVGパスを描画できます。用途に合わせて3つの方法が用意されています。</p><table tabindex="0"><thead><tr><th>方法</th><th>特徴と主な用途</th></tr></thead><tbody><tr><td><strong>図形（<a href="/mug-typography-docs/scripting/api-reference.html#section-shapes"><code>ctx.shapes</code></a>）</strong></td><td>本文のレイアウトとは独立して配置できる図形です。文字数・パーツ数の上限を消費せず、本文の背面（<code>layer = &quot;back&quot;</code>）や前面（<code>layer = &quot;front&quot;</code>）に座布団、飾り枠、背景アニメーション、パーティクルなどを重ねられます。図形どうしの親子関係（<code>parent</code>）や、本文カメラとは独立した3Dカメラ（<a href="/mug-typography-docs/scripting/api-reference.html#api-ctx-shape-cameras-declare"><code>ctx.shape_cameras</code></a>）にも対応しています。</td></tr><tr><td><strong>カスタムグリフ（<a href="/mug-typography-docs/scripting/api-reference.html#section-glyphs"><code>ctx.glyphs</code></a>）</strong></td><td>独自のパスに文字幅（<code>advance_x</code> / <code>advance_y</code>）を持たせ、1文字としてテキスト内に埋め込む機能です。文中にアイコンを混ぜたり、表の罫線や接続線を描いたりする用途に向いています。</td></tr><tr><td><strong>輪郭の差し替え（<a href="/mug-typography-docs/scripting/api-reference.html#section-path-context"><code>ctx.paths</code></a>）</strong></td><td><code>OnPath</code> で既存の文字パーツの輪郭（<code>path</code>）を直接書き換える機能です。特定の文字やパーツを別の形に変形させたいときに使います。</td></tr></tbody></table><p>パスデータは、SVGのパス文字列を読み込む <a href="/mug-typography-docs/scripting/api-reference.html#api-mt-svg-path"><code>mt.svg_path</code></a> や、直線・ベジェ曲線をコードで組み立てる <a href="/mug-typography-docs/scripting/api-reference.html#api-mt-drawing-path"><code>mt.drawing_path</code></a> で作成できます。詳しい仕様は <a href="/mug-typography-docs/scripting/api-reference.html#section-shapes">APIリファレンス</a> を参照してください。</p><h2 id="vscodeシミュレーター-mt-sim" tabindex="-1">VSCodeシミュレーター（MT Sim） <a class="header-anchor" href="#vscodeシミュレーター-mt-sim" aria-label="Permalink to &quot;VSCodeシミュレーター（MT Sim）&quot;">​</a></h2><p>配布ZIPの <code>scripting-simulator/</code> フォルダには、VSCode拡張「<strong>Mug Typography Scripting Simulator</strong>」（MT Sim）が同梱されています。DaVinci Resolve を起動しなくても、VSCode 上だけでスクリプトの作成とプレビューができます。</p><ul><li><strong>インストール</strong>: VSCodeの拡張機能ビューで「Install from VSIX...」を選び、同梱の <code>.vsix</code> ファイルを指定します。</li><li><strong>起動</strong>: <code>.lua</code> ファイルを開き、エディタ右上のプレビューアイコンかコマンドパレットの「Mug Typography Scripting Simulator」を実行します。ファイルを保存するとその場でプレビューが更新されます。</li><li><strong>プラグインへコピー</strong>: パネル上部の <strong>Copy Script</strong> でスクリプトをコピーし、プラグインの <strong>Paste Script</strong> で Script Text へ貼り付けます。</li><li><strong>編集支援</strong>: <code>ctx.*</code> や <code>mt.*</code> の入力補完とホバー説明が表示され、各コールバックで書き込み可能なフィールドだけが候補に出ます。</li><li><strong>シーン再現</strong>: タイムライン再生、フォント変更、文字・パーツ単位のインスペクタ、計算後の値一覧、3Dカメラのプレビューに対応しています。</li></ul><div class="info custom-block"><p class="custom-block-title">APIレベルとプラグインの対応</p><p>すべての機能を使うには、最新のプラグインを使用してください。新しいAPIを使ったサンプルやスクリプトは、古いプラグインでは動作しません。現在のプラグインのAPI Levelは13です。</p><p>VSCode拡張は、同じ配布ZIPに入っているプラグインと組み合わせて使ってください。</p><p>オンラインシミュレーターは最新のAPIに対応しているため、プラグインの更新を促す案内を表示します。更新したことを確認するまで、案内は表示され続けます。</p></div><div class="warning custom-block"><p class="custom-block-title">シミュレーターは近似プレビューです</p><p>MT Simのレイアウトと描画はプラグイン本体の近似です。グラデーションの補間や投影後のストローク品質などは簡略化されているため、最終的な仕上がりは必ずMug Typography本体で確認してください。</p></div><h3 id="ブラウザで試す" tabindex="-1">ブラウザで試す <a class="header-anchor" href="#ブラウザで試す" aria-label="Permalink to &quot;ブラウザで試す&quot;">​</a></h3><p>インストール不要で、ブラウザからそのまま試せる<a href="https://mug-lab-3.github.io/mug-typography-docs/simulator/" target="_blank" rel="noreferrer"><strong>オンラインシミュレーター ↗</strong></a>も公開しています。VSCode拡張版と同じ編集支援・サンプル集を備え、ちょっとした動作確認やAPIの学習に手軽に使えます。</p><h3 id="作品をギャラリーに公開する" tabindex="-1">作品をギャラリーに公開する <a class="header-anchor" href="#作品をギャラリーに公開する" aria-label="Permalink to &quot;作品をギャラリーに公開する&quot;">​</a></h3><p>作ったアニメーションは、オンラインシミュレーターの<strong>ギャラリー</strong>に公開できます。公開された作品はサンプルブラウザの <strong>コミュニティ</strong>に並び、誰でもカードから開いてスクリプトを読んだり、自分の制作の出発点にしたりできます。</p><p>投稿は<a href="https://github.com/mug-lab-3/mug-typography-community" target="_blank" rel="noreferrer"><strong>ギャラリーリポジトリ ↗</strong></a>から受け付けています（シミュレーターのメニューの <strong>Submit to Gallery</strong> からも開けます）。必要なファイルと手順はリポジトリのREADMEを参照してください。</p><h2 id="aiにスクリプトを書いてもらう" tabindex="-1">AIにスクリプトを書いてもらう <a class="header-anchor" href="#aiにスクリプトを書いてもらう" aria-label="Permalink to &quot;AIにスクリプトを書いてもらう&quot;">​</a></h2><p>Luaを書いたことがなくても、ChatGPTやClaudeなどのチャットAIに作りたい動きを伝えれば、 スクリプトを生成できます。ただしAIはMug Typographyの仕様を知らないため、 <strong>先にAI向けの仕様書を読み込ませる</strong>ことが必要です。これを省くと、 存在しない関数を使ったり、単位や向きを取り違えたスクリプトが返ってきます。</p><h3 id="手順" tabindex="-1">手順 <a class="header-anchor" href="#手順" aria-label="Permalink to &quot;手順&quot;">​</a></h3><ol><li><p><strong>仕様書を読み込ませる。</strong> 新しいチャットを開き、配布ZIPに同梱されている 次のファイルを<strong>添付</strong>して、「このAPI仕様書を読んでください」と伝えます。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>scripting-simulator/docs/lua_api_for_ai.md</span></span></code></pre></div><p>ファイルを添付できないAIの場合は、テキストエディタで開いて全文を貼り付けてください。 Web上のファイルを読み取れるAIであれば、次のURLを渡す方法もあります （読み取りに対応していないAIも多いため、まずは添付をおすすめします）。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://mug-lab-3.github.io/mug-typography-docs/lua_api_for_ai.md</span></span></code></pre></div></li><li><p><strong>読み込めたか確認する。</strong> 仕様書は大きなファイルのため、AIによっては 添付が読まれないことがあります。続けて次のように聞いてください。</p><blockquote><p><code>mt.stagger</code> の引数を、単位も含めて教えてください。</p></blockquote><p><code>time</code>（秒）、<code>index</code>（1始まり）、<code>delay</code>（秒）、<code>duration</code>（秒）と 答えられれば、正しく読み込めています。答えられない場合は<a href="#うまくいかないときは">後述の対処</a>を行ってください。</p></li><li><p><strong>作りたいアニメーションを指示する。</strong> 日本語で構いません。具体的に伝えるほど 意図に近いものが返ってきます。</p><blockquote><p>文字が1つずつ下から跳ね上がって登場し、最後に全体がゆっくり揺れるアニメーションを作ってください。</p></blockquote><p>3D操作を一切使わない作品なら、「<strong>2D専用として作って</strong>」「<strong>2D限定にして</strong>」と明記できます。対応したAIは、3D対応のScriptingプリセットでも2D描画経路を使う指定をスクリプトへ追加します。3D投影処理を省けるため描画速度の向上が期待できますが、CameraやGlobalなどの3Dインスペクタ設定とキーフレームはすべて無効になります。あとから3D操作を加える可能性がある場合は、2D専用にしないでください。</p></li><li><p><strong>返ってきたコードをコピーし</strong>、<strong>Script Text</strong> に貼り付けるか、 <strong>Paste Script</strong> で読み込みます。</p></li><li><p><strong>思った動きと違う場合は、そのまま伝えて修正してもらいます。</strong> 「跳ね上がりをもっと強く」「揺れは不要」のように、続けて指示できます。オンラインシミュレーターのメニューから <strong>AIプレビュー画像…</strong> を開くと、指定した再生範囲（またはクリップ全体）の複数フレームを並べた1枚のPNG画像をコピー・保存してAIチャットに添付でき、実際の見た目をAIに見せながら調整してもらえます。</p></li></ol><h3 id="うまくいかないときは" tabindex="-1">うまくいかないときは <a class="header-anchor" href="#うまくいかないときは" aria-label="Permalink to &quot;うまくいかないときは&quot;">​</a></h3><p>手順2の確認に答えられない、存在しない関数が使われる、単位や向きが明らかにおかしい ——いずれも仕様書が読まれていないサインです。次の順に試してください。</p><ol><li><strong>新しいチャットを開いて添付し直す。</strong> 会話が長くなると、最初に添付した内容が 参照されにくくなります。仕様書を読ませた直後に指示するのが最も確実です。</li><li><strong>添付ではなく全文を貼り付ける。</strong> テキストエディタで仕様書を開き、 全選択してチャット欄に貼り付けます。添付より確実に読み込まれます。</li><li><strong>別のAIを試す。</strong> 手元のPCで動かす小型のAIでは、仕様書が大きすぎて 読み込めないことがあります。</li></ol><div class="tip custom-block"><p class="custom-block-title">動作確認はシミュレーターが便利です</p><p>生成されたスクリプトにエラーがあっても、本体側ではエラー内容を確認できません。 MT Simやオンラインシミュレーターに貼り付けると、エラーメッセージと行番号が表示されるので、 それをAIに伝えるとそのまま修正してもらえます。</p></div><h3 id="mug-typography-mcp-プレビュー版" tabindex="-1">Mug Typography MCP（プレビュー版） <a class="header-anchor" href="#mug-typography-mcp-プレビュー版" aria-label="Permalink to &quot;Mug Typography MCP（プレビュー版）&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">プレビュー版です</p><p>Mug Typography MCPはプレビュー版です。機能や動作は予告なく変わることがあります。</p></div><p><strong>Mug Typography MCP</strong> は、ClaudeやCodexなどのAIクライアントに、Mug Typographyの使い方・Inspectorのパラメーター・Luaスクリプティング APIを説明するためのMCPサーバーです。 手順1の「仕様書を読み込ませる」作業の代わりに、AIがこのMCPから必要な情報を読み取ります。</p><ul><li><strong>仕様の説明</strong>: プラグインの機能、Inspectorのパラメーター、Luaスクリプティング API、同梱サンプルをAIに提供します。</li><li><strong>フォント名の解決</strong>: プラグインで選べるフォントの一覧を提供し、日本語の表示名からフォントを指定できます。</li><li><strong>スクリプトの確認</strong>: AIが書いたLuaスクリプトをシミュレーターで実行し、エラーや画面外に出る文字、値の変化、1フレームのプレビュー画像を確かめてから渡します。</li></ul><p>DaVinci Resolveそのものは操作しません。ノードの追加やScript Textへの設定までAIに任せるには、AIクライアントにDaVinci Resolve用のMCPも必要です。プレビュー画像は配置の目安で、仕上がりは必ずDaVinci Resolve上で確認してください。</p><p><strong>動作環境</strong></p><ul><li>Windows 11（64ビット）、またはmacOS 13.3以降（Apple Siliconのみ）</li><li>Mug Typographyをインストールした DaVinci Resolve Studio 21.1以降</li><li>次のいずれかのAIクライアント：Claude Desktop、Codex、Cursor、VS Code（GitHub Copilot）、Gemini CLI、Antigravity</li></ul><p><strong>使い方</strong></p><ol><li><p>インストーラー（Windows: <code>MugTypographyMCP-Setup.exe</code>、macOS: <code>MugTypographyMCP.pkg</code>）を実行します。使っているユーザーだけにインストールされ、見つかったAIクライアントへ自動で登録されます。</p></li><li><p>AIクライアントを再起動するか、MCPサーバーを再読み込みします。</p></li><li><p>作りたい演出をAIに頼みます。</p><blockquote><p>現在のクリップに、Mug Typographyで「HELLO」の文字が1文字ずつ上から落ちてくる演出を入れて</p></blockquote></li></ol><p>登録状態の確認や解除は、Windowsではスタートメニューの「Mug Typography MCP」、macOSでは<code>~/Applications</code>の<code>MugTypographyMCP</code>から開く画面で行えます。画面の <strong>Check the connection</strong> を押すと、AIが送る内容と返ってくる内容を確かめられます。</p><p>macOSでは、ダウンロードしたインストーラーが「検証できません」と表示されることがあります。その場合は「システム設定 &gt; プライバシーとセキュリティ」を開き、下へスクロールして<code>MugTypographyMCP.pkg</code>の横の「このまま開く」を押してください。</p><h2 id="サンプルとapiリファレンス" tabindex="-1">サンプルとAPIリファレンス <a class="header-anchor" href="#サンプルとapiリファレンス" aria-label="Permalink to &quot;サンプルとAPIリファレンス&quot;">​</a></h2><p>配布ZIPの <code>scripting-simulator/samples/</code> に、そのまま使えるLuaサンプルが多数入っています。</p><ul><li><code>reference/</code> — 基本モデルと各APIの使い方をジャンル別に学べる短い学習用サンプル</li><li><code>showcase/</code> — タイプライター、バウンス登場、ネオン、背景・図形演出、3Dカメラワークなど完成品のアニメーション集</li><li><code>diagnostics/</code> — 環境・APIの内部動作確認用スクリプト</li></ul><p><code>reference/</code> もジャンルごとに分かれており、基礎・実行の流れ（<code>RBS</code>）、時間・アニメーション（<code>RTM</code>）、テキスト・レイアウト（<code>RLY</code>）、色・質感・描画（<code>RAP</code>）、パス・カスタムグリフ・図形（<code>RPT</code>）、乱数・ノイズ（<code>RRN</code>）、3D・カメラ（<code>RCM</code>）を目的別に確認できます。</p><p>シミュレーターの<strong>サンプルブラウザ</strong>では、ジャンル別の一覧やキーワード検索（サンプルID・ジャンル名・API名）からサンプルを探せます。</p><ul><li><strong>プレビューを再生</strong>: 編集中のスクリプトを上書きせずに、その場でサンプルのアニメーションを再生して動きを確かめられます。</li><li><strong>エディタで開く</strong>: 選んだサンプルをエディタに読み込み、そのまま改造したり中身を読んだりできます。</li><li><strong>Scripting Check</strong>: メニューから実行すると、編集中スクリプトを変えずに Scripting 機能の動作診断を行えます。</li></ul><p>APIの詳しい仕様は「<a href="/mug-typography-docs/scripting/api-reference.html">Luaスクリプティング APIリファレンス</a>」を参照してください（オフライン用の同じドキュメントが配布ZIPの <code>scripting-simulator/docs/</code> にも入っています）。</p><p>パラメーターの詳細と制限事項は「<a href="/mug-typography-docs/reference/reference-scripting-settings.html">スクリプティング設定 (Scripting Settings)</a>」を参照してください。</p>`,54))])}const y=a(p,[["render",c]]);export{k as __pageData,y as default};
